import pyomo.environ as pyo

DATA = {
    "workers": ["X", "Y", "Z"],
    "cost": {"X": 8, "Y": 6, "Z": 10},
    "cap": {"X": 12, "Y": 8, "Z": 6},
    "total_shift_cap": 24,
    "x_minus_y_gap": 2,     # x >= y + 2
    "y_z_balance": 4,       # |y - z| <= 4
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.W = pyo.Set(initialize=d["workers"])

    def shift_bounds(m, w):
        return (0, d["cap"][w])

    model.shifts = pyo.Var(
        model.W,
        within=pyo.NonNegativeIntegers,
        bounds=shift_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][w] * m.shifts[w] for w in m.W)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_cap_rule(m):
        return sum(m.shifts[w] for w in m.W) <= d["total_shift_cap"]

    model.total_shift_cap = pyo.Constraint(rule=total_cap_rule)

    def skill_gap_rule(m):
        return m.shifts["X"] - m.shifts["Y"] >= d["x_minus_y_gap"]

    model.skill_gap = pyo.Constraint(rule=skill_gap_rule)

    def balance_upper_rule(m):
        return m.shifts["Y"] - m.shifts["Z"] <= d["y_z_balance"]

    model.balance_upper = pyo.Constraint(rule=balance_upper_rule)

    def balance_lower_rule(m):
        return m.shifts["Z"] - m.shifts["Y"] <= d["y_z_balance"]

    model.balance_lower = pyo.Constraint(rule=balance_lower_rule)

    return model


